  1671  static void decode_restoration_mode(AV1_COMMON *cm,
  1672                                      struct aom_read_bit_buffer *rb) {
  1673    assert(!cm->all_lossless);
  1674    const int num_planes = av1_num_planes(cm);
  1675    if (cm->allow_intrabc) return;
  1676    int all_none = 1, chroma_none = 1;
  1677    for (int p = 0; p < num_planes; ++p) {
  1678      RestorationInfo *rsi = &cm->rst_info[p];
  1679      if (aom_rb_read_bit(rb)) {
  1680        rsi->frame_restoration_type =
  1681            aom_rb_read_bit(rb) ? RESTORE_SGRPROJ : RESTORE_WIENER;
  1682      } else {
  1683        rsi->frame_restoration_type =
  1684            aom_rb_read_bit(rb) ? RESTORE_SWITCHABLE : RESTORE_NONE;
  1685      }
  1686      if (rsi->frame_restoration_type != RESTORE_NONE) {
  1687        all_none = 0;
  1688        chroma_none &= p == 0;
  1689      }
  1690    }
  1691    if (!all_none) {
  1692      assert(cm->seq_params.sb_size == BLOCK_64X64 ||
  1693             cm->seq_params.sb_size == BLOCK_128X128);
  1694      const int sb_size = cm->seq_params.sb_size == BLOCK_128X128 ? 128 : 64;
  1695
  1696      for (int p = 0; p < num_planes; ++p)
  1697        cm->rst_info[p].restoration_unit_size = sb_size;
  1698
  1699      RestorationInfo *rsi = &cm->rst_info[0];
  1700
  1701      if (sb_size == 64) {
  1702        rsi->restoration_unit_size <<= aom_rb_read_bit(rb);
  1703      }
  1704      if (rsi->restoration_unit_size > 64) {
  1705        rsi->restoration_unit_size <<= aom_rb_read_bit(rb);
  1706      }
  1707    } else {
  1708      const int size = RESTORATION_UNITSIZE_MAX;
  1709      for (int p = 0; p < num_planes; ++p)
  1710        cm->rst_info[p].restoration_unit_size = size;
  1711    }
  1712
  1713    if (num_planes > 1) {
  1714      int s = AOMMIN(cm->seq_params.subsampling_x, cm->seq_params.subsampling_y);
  1715      if (s && !chroma_none) {
  1716        cm->rst_info[1].restoration_unit_size =
  1717            cm->rst_info[0].restoration_unit_size >> (aom_rb_read_bit(rb) * s);
  1718      } else {
  1719        cm->rst_info[1].restoration_unit_size =
  1720            cm->rst_info[0].restoration_unit_size;
  1721      }
  1722      cm->rst_info[2].restoration_unit_size =
  1723          cm->rst_info[1].restoration_unit_size;
  1724    }
  1725  }
