  1727  static void read_wiener_filter(int wiener_win, WienerInfo *wiener_info,
  1728                                 WienerInfo *ref_wiener_info, aom_reader *rb) {
  1729    memset(wiener_info->vfilter, 0, sizeof(wiener_info->vfilter));
  1730    memset(wiener_info->hfilter, 0, sizeof(wiener_info->hfilter));
  1731
  1732    if (wiener_win == WIENER_WIN)
  1733      wiener_info->vfilter[0] = wiener_info->vfilter[WIENER_WIN - 1] =
  1734          aom_read_primitive_refsubexpfin(
  1735              rb, WIENER_FILT_TAP0_MAXV - WIENER_FILT_TAP0_MINV + 1,
  1736              WIENER_FILT_TAP0_SUBEXP_K,
  1737              ref_wiener_info->vfilter[0] - WIENER_FILT_TAP0_MINV, ACCT_STR) +
  1738          WIENER_FILT_TAP0_MINV;
  1739    else
  1740      wiener_info->vfilter[0] = wiener_info->vfilter[WIENER_WIN - 1] = 0;
  1741    wiener_info->vfilter[1] = wiener_info->vfilter[WIENER_WIN - 2] =
  1742        aom_read_primitive_refsubexpfin(
  1743            rb, WIENER_FILT_TAP1_MAXV - WIENER_FILT_TAP1_MINV + 1,
  1744            WIENER_FILT_TAP1_SUBEXP_K,
  1745            ref_wiener_info->vfilter[1] - WIENER_FILT_TAP1_MINV, ACCT_STR) +
  1746        WIENER_FILT_TAP1_MINV;
  1747    wiener_info->vfilter[2] = wiener_info->vfilter[WIENER_WIN - 3] =
  1748        aom_read_primitive_refsubexpfin(
  1749            rb, WIENER_FILT_TAP2_MAXV - WIENER_FILT_TAP2_MINV + 1,
  1750            WIENER_FILT_TAP2_SUBEXP_K,
  1751            ref_wiener_info->vfilter[2] - WIENER_FILT_TAP2_MINV, ACCT_STR) +
  1752        WIENER_FILT_TAP2_MINV;
  1753    // The central element has an implicit +WIENER_FILT_STEP
  1754    wiener_info->vfilter[WIENER_HALFWIN] =
  1755        -2 * (wiener_info->vfilter[0] + wiener_info->vfilter[1] +
  1756              wiener_info->vfilter[2]);
  1757
  1758    if (wiener_win == WIENER_WIN)
  1759      wiener_info->hfilter[0] = wiener_info->hfilter[WIENER_WIN - 1] =
  1760          aom_read_primitive_refsubexpfin(
  1761              rb, WIENER_FILT_TAP0_MAXV - WIENER_FILT_TAP0_MINV + 1,
  1762              WIENER_FILT_TAP0_SUBEXP_K,
  1763              ref_wiener_info->hfilter[0] - WIENER_FILT_TAP0_MINV, ACCT_STR) +
  1764          WIENER_FILT_TAP0_MINV;
  1765    else
  1766      wiener_info->hfilter[0] = wiener_info->hfilter[WIENER_WIN - 1] = 0;
  1767    wiener_info->hfilter[1] = wiener_info->hfilter[WIENER_WIN - 2] =
  1768        aom_read_primitive_refsubexpfin(
  1769            rb, WIENER_FILT_TAP1_MAXV - WIENER_FILT_TAP1_MINV + 1,
  1770            WIENER_FILT_TAP1_SUBEXP_K,
  1771            ref_wiener_info->hfilter[1] - WIENER_FILT_TAP1_MINV, ACCT_STR) +
  1772        WIENER_FILT_TAP1_MINV;
  1773    wiener_info->hfilter[2] = wiener_info->hfilter[WIENER_WIN - 3] =
  1774        aom_read_primitive_refsubexpfin(
  1775            rb, WIENER_FILT_TAP2_MAXV - WIENER_FILT_TAP2_MINV + 1,
  1776            WIENER_FILT_TAP2_SUBEXP_K,
  1777            ref_wiener_info->hfilter[2] - WIENER_FILT_TAP2_MINV, ACCT_STR) +
  1778        WIENER_FILT_TAP2_MINV;
  1779    // The central element has an implicit +WIENER_FILT_STEP
  1780    wiener_info->hfilter[WIENER_HALFWIN] =
  1781        -2 * (wiener_info->hfilter[0] + wiener_info->hfilter[1] +
  1782              wiener_info->hfilter[2]);
  1783    memcpy(ref_wiener_info, wiener_info, sizeof(*wiener_info));
