  1786  static void read_sgrproj_filter(SgrprojInfo *sgrproj_info,
  1787                                  SgrprojInfo *ref_sgrproj_info, aom_reader *rb) {
  1788    sgrproj_info->ep = aom_read_literal(rb, SGRPROJ_PARAMS_BITS, ACCT_STR);
  1789    const sgr_params_type *params = &sgr_params[sgrproj_info->ep];
  1790
  1791    if (params->r[0] == 0) {
  1792      sgrproj_info->xqd[0] = 0;
  1793      sgrproj_info->xqd[1] =
  1794          aom_read_primitive_refsubexpfin(
  1795              rb, SGRPROJ_PRJ_MAX1 - SGRPROJ_PRJ_MIN1 + 1, SGRPROJ_PRJ_SUBEXP_K,
  1796              ref_sgrproj_info->xqd[1] - SGRPROJ_PRJ_MIN1, ACCT_STR) +
  1797          SGRPROJ_PRJ_MIN1;
  1798    } else if (params->r[1] == 0) {
  1799      sgrproj_info->xqd[0] =
  1800          aom_read_primitive_refsubexpfin(
  1801              rb, SGRPROJ_PRJ_MAX0 - SGRPROJ_PRJ_MIN0 + 1, SGRPROJ_PRJ_SUBEXP_K,
  1802              ref_sgrproj_info->xqd[0] - SGRPROJ_PRJ_MIN0, ACCT_STR) +
  1803          SGRPROJ_PRJ_MIN0;
  1804      sgrproj_info->xqd[1] = clamp((1 << SGRPROJ_PRJ_BITS) - sgrproj_info->xqd[0],
  1805                                   SGRPROJ_PRJ_MIN1, SGRPROJ_PRJ_MAX1);
  1806    } else {
  1807      sgrproj_info->xqd[0] =
  1808          aom_read_primitive_refsubexpfin(
  1809              rb, SGRPROJ_PRJ_MAX0 - SGRPROJ_PRJ_MIN0 + 1, SGRPROJ_PRJ_SUBEXP_K,
  1810              ref_sgrproj_info->xqd[0] - SGRPROJ_PRJ_MIN0, ACCT_STR) +
  1811          SGRPROJ_PRJ_MIN0;
  1812      sgrproj_info->xqd[1] =
  1813          aom_read_primitive_refsubexpfin(
  1814              rb, SGRPROJ_PRJ_MAX1 - SGRPROJ_PRJ_MIN1 + 1, SGRPROJ_PRJ_SUBEXP_K,
  1815              ref_sgrproj_info->xqd[1] - SGRPROJ_PRJ_MIN1, ACCT_STR) +
  1816          SGRPROJ_PRJ_MIN1;
  1817    }
  1818
  1819    memcpy(ref_sgrproj_info, sgrproj_info, sizeof(*sgrproj_info));
  1820  }
