  1822  static void loop_restoration_read_sb_coeffs(const AV1_COMMON *const cm,
  1823                                              MACROBLOCKD *xd,
  1824                                              aom_reader *const r, int plane,
  1825                                              int runit_idx) {
  1826    const RestorationInfo *rsi = &cm->rst_info[plane];
  1827    RestorationUnitInfo *rui = &rsi->unit_info[runit_idx];
  1828    if (rsi->frame_restoration_type == RESTORE_NONE) return;
  1829
  1830    assert(!cm->all_lossless);
  1831
  1832    const int wiener_win = (plane > 0) ? WIENER_WIN_CHROMA : WIENER_WIN;
  1833    WienerInfo *wiener_info = xd->wiener_info + plane;
  1834    SgrprojInfo *sgrproj_info = xd->sgrproj_info + plane;
  1835
  1836    if (rsi->frame_restoration_type == RESTORE_SWITCHABLE) {
  1837      rui->restoration_type =
  1838          aom_read_symbol(r, xd->tile_ctx->switchable_restore_cdf,
  1839                          RESTORE_SWITCHABLE_TYPES, ACCT_STR);
  1840      switch (rui->restoration_type) {
  1841        case RESTORE_WIENER:
  1842          read_wiener_filter(wiener_win, &rui->wiener_info, wiener_info, r);
  1843          break;
  1844        case RESTORE_SGRPROJ:
  1845          read_sgrproj_filter(&rui->sgrproj_info, sgrproj_info, r);
  1846          break;
  1847        default: assert(rui->restoration_type == RESTORE_NONE); break;
