  1856    } else if (rsi->frame_restoration_type == RESTORE_SGRPROJ) {
  1857      if (aom_read_symbol(r, xd->tile_ctx->sgrproj_restore_cdf, 2, ACCT_STR)) {
  1858        rui->restoration_type = RESTORE_SGRPROJ;
  1859        read_sgrproj_filter(&rui->sgrproj_info, sgrproj_info, r);
  1860      } else {
  1861        rui->restoration_type = RESTORE_NONE;
  1862      }
  1863    }
